  examples=[("随着中国的发展，越来越多的外国学生来到中国的大学学习。","Suízhe Zhōngguó de fāzhǎn, yuèláiyuè duō de wàiguó xuésheng láidào Zhōngguó de dàxué xuéxí.","Хятад хөгжихийн хэрээр Хятадын их сургуульд сурахаар ирэх гадаад оюутан улам олширч байна."),
            ("随着中文水平的提高，我现在能看懂中文报纸了。","Suízhe Zhōngwén shuǐpíng de tígāo, wǒ xiànzài néng kàndǒng Zhōngwén bàozhǐ le.","Хятад хэлний түвшин дээшлэх тусам би одоо хятад сонин ойлгож уншиж чаддаг боллоо."),
            ("随着小区的环境越来越好，来这里买房子的人也变多了。","Suízhe xiǎoqū de huánjìng yuèláiyuè hǎo, lái zhèlǐ mǎi fángzi de rén yě biàn duō le.","Хорооллын орчин улам сайжирах тусам энд байр авахаар ирэх хүмүүс ч олширсон."),
            ("随着天气变冷，出门的人越来越少。","Suízhe tiānqì biàn lěng, chūmén de rén yuèláiyuè shǎo.","Цаг агаар хүйтрэх тусам гадуур гарах хүн улам цөөрч байна.")],
  mistakes=[("随着我学习中文，我很喜欢中国。","随着学习中文的时间越来越长，我越来越喜欢中国。","随着-ийн ард өөрчлөлт, ард нь хамт өөрчлөгдөх үр дүн (越来越) хэрэгтэй."),
            ("随着中文水平提高了，我能看懂报纸。","随着中文水平的提高，我能看懂报纸。","随着-ийн ард 了 биш, 的 + нэр үг (提高) эсвэл өөрчлөлтийн үг орно.")],
  check=("«Цаг агаар дулаарах тусам» — аль нь зөв вэ?",["随着天气变暖","因为天气变暖了随着"],0),
